def load_json(rel, default):
    p = ROOT / rel
    if not p.exists():
        return default
    return json.loads(p.read_text(encoding="utf-8"))


def save_json(rel, value):
    p = ROOT / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(value, ensure_ascii=False, separators=(",", ":")) + "\n", encoding="utf-8")


def upsert(items, item, key="id", prepend=False):
    for i, existing in enumerate(items):
        if existing.get(key) == item.get(key):
            items[i] = item
            return
    if prepend:
        items.insert(0, item)
    else:
        items.append(item)


def append_unique(items, item, key=None):
    if key:
        if any(x.get(key) == item.get(key) for x in items if isinstance(x, dict)):
            return
    elif item in items:
        return
    items.append(item)


